22	/**
23	 * Maps Owner & OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public abstract class OwnerMapper {
27	
28	    /** Used to count the members of an owner's household when deriving derived fields. */
29	    @Autowired
30	    protected ClinicService clinicService;
31	
32	    /** Single source of truth for the city-to-region mapping behind an owner's locality. */
33	    @Autowired
34	    protected CityRegionResolver cityRegionResolver;
35	
36	    /** Formats the stored E.164 telephone into its human-readable display form. */
37	    @Autowired
38	    protected TelephoneNormalizer telephoneNormalizer;
39	
40	    @Mapping(target = "displayName",
41	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
42	    @Mapping(target = "initials", expression = "java(initials(owner))")
43	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
44	    @Mapping(target = "locality", expression = "java(locality(owner))")
45	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
46	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneNormalizer.toDisplayForm(owner.getTelephone()))")
47	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
48	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
49	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
50	    public abstract OwnerDto toOwnerDto(Owner owner);
51	
52	    /**
53	     * The owner's age band derived from {@code birthDate} relative to the
54	     * {@code registrationDate}: 'MINOR' when under 18, 'ADULT' from 18 to 64
55	     * inclusive and 'SENIOR' at 65 or older. Returns null when either date is
56	     * absent so no band can be computed.
57	     */
58	    OwnerDto.AgeBandEnum ageBand(Owner owner) {
59	        LocalDate birthDate = owner.getBirthDate();
60	        LocalDate registrationDate = owner.getRegistrationDate();
61	        if (birthDate == null || registrationDate == null) {
62	            return null;
63	        }
64	        int age = Period.between(birthDate, registrationDate).getYears();
65	        if (age < 18) {
66	            return OwnerDto.AgeBandEnum.MINOR;
67	        }
68	        if (age < 65) {
69	            return OwnerDto.AgeBandEnum.ADULT;
70	        }
71	        return OwnerDto.AgeBandEnum.SENIOR;
72	    }
73	
74	    /**
75	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
76	     * contained in the customerCode, or null when no customerCode has been assigned.
77	     */
78	    Integer checkDigit(Owner owner) {
79	        String customerCode = owner.getCustomerCode();
80	        return customerCode == null ? null : luhn(customerCode);
81	    }
82	
83	    /**
84	     * The Luhn check digit (0-9) over the digits contained in {@code s}: from the rightmost
85	     * digit leftward, every second digit is doubled (the rightmost first) with digits over 9
86	     * reduced by 9, and the check digit makes the total a multiple of ten.
87	     */
88	    static int luhn(String s) {
89	        int sum = 0;
90	        boolean doubling = true;
91	        for (int i = s.length() - 1; i >= 0; i--) {
92	            char c = s.charAt(i);
93	            if (c < '0' || c > '9') {
94	                continue;
95	            }
96	            int d = c - '0';
97	            if (doubling) {
98	                d *= 2;
99	                if (d > 9) {
100	                    d -= 9;
101	                }
102	            }
103	            sum += d;
104	            doubling = !doubling;
105	        }
106	        return (10 - (sum % 10)) % 10;
107	    }
108	
109	    /**
110	     * The owner's derived identity key: the normalized telephone, the email (or an empty
111	     * string when absent) and the householdId joined by '|'. This single key is the sole
112	     * basis for duplicate detection on create — two owners are duplicates only when their
113	     * whole identityKey matches, so members of one household with different telephones
114	     * (and hence different keys) are all permitted.
115	     */
116	    public static String identityKey(Owner owner) {
117	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
118	        String email = owner.getEmail() == null ? "" : owner.getEmail();
119	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
120	        return telephone + "|" + email + "|" + householdId;
121	    }
122	
123	    /**
124	     * The owner's preferred contact channel: 'EMAIL' when an email address is
125	     * present, otherwise 'PHONE'.
126	     */
127	    String contactPreference(Owner owner) {
128	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
129	        return hasEmail ? "EMAIL" : "PHONE";
130	    }
131	
132	    /**
133	     * The owner's locality: the REGION component of the customerCode identity (the part before
134	     * the first '-' of {@code '<REGION>-<HASH8>'}). When no customerCode has been assigned this
135	     * falls back to the canonical region derived from the owner via {@link CityRegionResolver},
136	     * preferring the postcode over the city, or 'UNKNOWN' when neither yields a known region.
137	     */
138	    String locality(Owner owner) {
139	        String customerCode = owner.getCustomerCode();
140	        if (customerCode != null) {
141	            int dash = customerCode.indexOf('-');
142	            if (dash >= 0) {
143	                return customerCode.substring(0, dash);
144	            }
145	        }
146	        return cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
147	    }
148	
149	    /**
150	     * The owner's numeric membership level from 1 to 4: starting at 1, plus 1 when an
151	     * email address is present, plus 1 when namesakeCount is 0, plus 1 when the owner's
152	     * tenure is more than 365 days, capped at 4. Because a newly created owner has zero
153	     * tenure, a new owner never exceeds level 3.
154	     */
155	    public int membershipLevel(Owner owner) {
156	        int level = 1;
157	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
158	        if (hasEmail) {
159	            level++;
160	        }
161	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
162	        if (uniqueName) {
